import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

const DATA_DIR = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  'data'
);

const TOOL_SCHEMA = {
  name: 'file_metadata',
  description:
    'Return metadata (relative path, byte size, lowercase extension) for a file under the workspace data directory. Does not expose file contents.',
  inputSchema: {
    type: 'object',
    properties: {
      path: {
        type: 'string',
        description: 'Path to a file under the data directory.'
      }
    },
    required: ['path'],
    additionalProperties: false
  }
};

export async function listTools() {
  return [TOOL_SCHEMA];
}

function fail(message) {
  const error = new Error(message);
  error.isToolError = true;
  return error;
}

export async function callTool(name, args = {}) {
  if (name !== 'file_metadata') {
    throw fail(`Unknown tool: ${name}`);
  }

  const { path: rawPath } = args;
  if (typeof rawPath !== 'string' || rawPath.length === 0) {
    throw fail('path is required and must be a non-empty string');
  }

  // Reject absolute paths and anything that escapes the data directory.
  const resolved = path.resolve(DATA_DIR, rawPath);
  const rel = path.relative(DATA_DIR, resolved);
  if (rel.startsWith('..') || path.isAbsolute(rawPath)) {
    throw fail('Path must stay within the data directory');
  }

  let stat;
  try {
    stat = fs.statSync(resolved);
  } catch {
    throw fail('File not found: ' + rawPath);
  }

  if (!stat.isFile()) {
    throw fail('Not a file: ' + rawPath);
  }

  const relativePath = path.relative(DATA_DIR, resolved).split(path.sep).join('/');
  const ext = path.extname(resolved).toLowerCase();
  const size = stat.size;

  return {
    content: [
      {
        type: 'text',
        text: `path: ${relativePath}\nsize: ${size} bytes\nextension: ${ext}`
      }
    ]
  };
}

